def is_iterable(thing):
    try:
        iter(thing)
    except TypeError:
        return False
    return True


def flatten(iterable):
    """Flatten nested iterables in order, omitting None values."""
    flattened = []
    stack = [iter(iterable)]
    while stack:
        try:
            item = next(stack[-1])
        except StopIteration:
            stack.pop()
            continue
        if item is None:
            continue
        if isinstance(item, (str, bytes)):
            flattened.append(item)
            continue
        try:
            nested = iter(item)
        except TypeError:
            flattened.append(item)
        else:
            stack.append(nested)
    return flattened
